# muckscraperHeadlinesGoogleNEW/aggregator/models.py
# aggregator/models.py

from . import db
from .article_signals import is_roundup_article
from datetime import datetime
from pgvector.sqlalchemy import Vector
from sqlalchemy.dialects.postgresql import TSVECTOR
from sqlalchemy.orm import deferred
from flask_login import UserMixin
from werkzeug.security import generate_password_hash, check_password_hash

# Full-text search vectors (aggregator/search.py), generated by Postgres from
# the row's own text so they can never go stale. Weights: A titles, B
# summaries, C source and deep report, D article text. The stored HTML's tags
# are dropped by the text parser. Must stay identical to the migration that
# added them (migrations/versions/a9c4e2f7b1d5_postgres_full_text_search.py).
STORY_SEARCH_VECTOR_SQL = (
    "setweight(to_tsvector('english'::regconfig, coalesce(title, '')), 'A') || "
    "setweight(to_tsvector('english'::regconfig, coalesce(headline, '')), 'A') || "
    "setweight(to_tsvector('english'::regconfig, coalesce(summary, '')), 'B') || "
    "setweight(to_tsvector('english'::regconfig, left(coalesce(deep_report, ''), 8000)), 'C')"
)
ARTICLE_SEARCH_VECTOR_SQL = (
    "setweight(to_tsvector('english'::regconfig, coalesce(title, '')), 'A') || "
    "setweight(to_tsvector('english'::regconfig, coalesce(summary, '')), 'B') || "
    "setweight(to_tsvector('english'::regconfig, coalesce(source, '')), 'C') || "
    "setweight(to_tsvector('english'::regconfig, left(coalesce(content, ''), 6000)), 'D')"
)

# Many-to-many junction tables
story_topics = db.Table("story_topics",
    db.Column("story_id", db.Integer, db.ForeignKey("stories.id"), primary_key=True),
    db.Column("topic_id", db.Integer, db.ForeignKey("topics.id"), primary_key=True)
)

article_topics = db.Table("article_topics",
    db.Column("article_id", db.Integer, db.ForeignKey("articles.id"), primary_key=True),
    db.Column("topic_id", db.Integer, db.ForeignKey("topics.id"), primary_key=True)
)


class Outlet(db.Model):
    __tablename__ = "outlets"

    id          = db.Column(db.Integer, primary_key=True)
    name        = db.Column(db.String, nullable=False)
    url         = db.Column(db.String)
    description = db.Column(db.Text)
    bias_score  = db.Column(db.Float)
    bias_retry_count = db.Column(db.Integer, default=0, nullable=False, server_default='0')
    allsides_bias_score = db.Column(db.Float, nullable=True)
    bias_source = db.Column(db.String(16), nullable=True)
    # The outlet's icon for cards with no article image, resolved per domain
    # by news_fetcher/outlet_logos.py (2026-10-22).
    logo_url = db.Column(db.String, nullable=True)
    logo_checked_at = db.Column(db.DateTime, nullable=True)
    # ISO country code (empty = US) and "public"/"state" funding, set by
    # apply_outlet_origins() from aggregator/outlet_origins.py (2026-10-23).
    country = db.Column(db.String(2), nullable=True)
    funding = db.Column(db.String(16), nullable=True)

    articles = db.relationship("Article", backref="outlet", lazy=True)

    @property
    def is_international(self):
        from aggregator.outlet_origins import is_international
        return is_international(self.country)

    @property
    def flag(self):
        """The country's flag emoji, for outlets based outside the US."""
        if not self.is_international or len(self.country) != 2:
            return None
        return "".join(chr(0x1F1E6 + ord(c) - ord("A")) for c in self.country.upper())

    @property
    def reporting(self):
        """A level from aggregator/outlet_reporting.py (very_high ... low), or None."""
        from aggregator.outlet_reporting import reporting_for
        return reporting_for(self.name)

    @property
    def origin_label(self):
        """'Germany · Public broadcaster', for the flag's tooltip."""
        from aggregator.outlet_origins import country_name, funding_name
        if not self.is_international:
            return None
        parts = [country_name(self.country), funding_name(self.funding)]
        return " · ".join(p for p in parts if p)


class Topic(db.Model):
    __tablename__ = "topics"

    id         = db.Column(db.Integer, primary_key=True)
    name       = db.Column(db.String, unique=True, nullable=False)
    icon       = db.Column(db.String(4), nullable=True)
    sort_order = db.Column(db.Integer, nullable=True)
    is_active  = db.Column(db.Boolean, nullable=False, default=True, server_default="true")

    stories  = db.relationship("Story",   secondary=story_topics,  back_populates="topics")
    articles = db.relationship("Article", secondary=article_topics, back_populates="topics")


class Story(db.Model):
    __tablename__ = "stories"
    __table_args__ = (
        db.Index("ix_stories_created_at", "created_at"),
        db.Index("ix_stories_search_vector", "search_vector", postgresql_using="gin"),
        db.Index("ix_stories_title_trgm", "title", postgresql_using="gin", postgresql_ops={"title": "gin_trgm_ops"}),
        db.Index("ix_stories_headline_trgm", "headline", postgresql_using="gin", postgresql_ops={"headline": "gin_trgm_ops"}),
    )

    id         = db.Column(db.Integer, primary_key=True)
    title      = db.Column(db.String, nullable=False)
    headline   = db.Column(db.String)
    summary    = db.Column(db.Text)
    deep_report = db.Column(db.Text)
    headline_score = db.Column(db.Float, default=0.0)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    summary_generated_at = db.Column(db.DateTime, nullable=True)
    # When `headline` was last written, so the batch headline pass can tell a
    # stale headline (story gained an article since) from a current one. NULL
    # on every pre-existing row, which the pass treats as stale.
    headline_generated_at = db.Column(db.DateTime, nullable=True)
    # A short reader-facing paragraph on what the Op/Ed columns linked to this
    # story argue (news_fetcher/opinion_linker.py). NULL until the story has
    # at least two linked columns; regenerated when a new one is linked.
    opinion_roundup = db.Column(db.Text, nullable=True)
    opinion_roundup_generated_at = db.Column(db.DateTime, nullable=True)
    # Deferred: only search reads it, so loading a story never pulls it in.
    search_vector = deferred(db.Column(TSVECTOR, db.Computed(STORY_SEARCH_VECTOR_SQL, persisted=True)))

    topics   = db.relationship("Topic",   secondary=story_topics,  back_populates="stories")
    articles = db.relationship("Article", backref="story", lazy=True)
    edition_stories = db.relationship("EditionStory", back_populates="story", cascade="all, delete-orphan", overlaps="story")

    @property
    def last_updated(self):
        """Latest publication date among all articles in this story."""
        if not self.articles:
            return self.created_at
        return max((a.date for a in self.articles if a.date), default=self.created_at)

    @property
    def site_articles(self):
        """The story's articles without copies of another article in it
        (aggregator/article_copies.py): what muckscraper.news shows."""
        from aggregator.article_copies import original_articles
        return original_articles(self.articles)

    @property
    def has_ai_headline(self):
        return len(self.articles) >= 2 and bool((self.headline or "").strip())

    @property
    def display_headline(self):
        return self.headline if self.has_ai_headline else self.title


class Article(db.Model):
    __tablename__ = "articles"
    __table_args__ = (
        db.Index("ix_articles_url",        "url"),
        db.Index("ix_articles_date",       "date"),
        # Every run's "what came in recently" queries (quality report, copy
        # detector, opinion linker, scrape blocklist) filter on fetched_at.
        db.Index("ix_articles_fetched_at", "fetched_at"),
        db.Index("ix_articles_outlet_id",  "outlet_id"),
        db.Index("ix_articles_story_id",   "story_id"),
        db.Index("ix_articles_bias_score", "bias_score"),
        db.Index("ix_articles_search_vector", "search_vector", postgresql_using="gin"),
        db.Index("ix_articles_title_trgm", "title", postgresql_using="gin", postgresql_ops={"title": "gin_trgm_ops"}),
    )

    id         = db.Column(db.Integer, primary_key=True)
    title      = db.Column(db.String, nullable=False)
    content    = db.Column(db.Text)
    source     = db.Column(db.String)
    url        = db.Column(db.String, unique=True)
    outlet_id  = db.Column(db.Integer, db.ForeignKey("outlets.id"))
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id"))
    date       = db.Column(db.DateTime, default=datetime.utcnow) # This is Published Date
    fetched_at = db.Column(db.DateTime, default=datetime.utcnow) # When we actually scraped it
    bias_score = db.Column(db.Float)
    # Where bias_score came from: None while it is a copy of the outlet's,
    # "ai" or "reader" once the article was rated on its own
    # (aggregator/article_lean.py). Outlet re-syncs leave rated articles alone.
    bias_source = db.Column(db.String(16), nullable=True)
    image_url  = db.Column(db.String)
    embedding  = db.Column(Vector(768))
    summary    = db.Column(db.Text)
    deep_analysis = db.Column(db.Text)
    scrape_audited = db.Column(db.Boolean, default=False, nullable=False, server_default='false')
    scrape_status = db.Column(db.String(32), nullable=False, default="pending", server_default='pending')
    scrape_method = db.Column(db.String(255), nullable=True)
    scrape_failure_reason = db.Column(db.String(1024), nullable=True)
    scrape_http_status = db.Column(db.Integer, nullable=True)
    grouping_match_method = db.Column(db.String(32), nullable=True)
    grouping_confidence = db.Column(db.Float, nullable=True)
    grouping_candidate_story_ids = db.Column(db.Text, nullable=True)
    grouping_needs_review = db.Column(db.Boolean, default=False, nullable=False, server_default='false')
    grouping_reviewed_at = db.Column(db.DateTime, nullable=True)
    # Same text as another article in the story (republished, or the same
    # wire copy); set by news_fetcher/copy_detector.py. The aggregator still
    # lists it; muckscraper.news leaves it out (aggregator/article_copies.py).
    copy_of_id = db.Column(db.Integer, db.ForeignKey("articles.id", ondelete="SET NULL"), nullable=True, index=True)
    copy_overlap = db.Column(db.Float, nullable=True)
    copy_checked_at = db.Column(db.DateTime, nullable=True)
    # Set when outlet_logos.retry_missing_images fetched the page again for an
    # og:image, found or not, so each article is retried once.
    image_checked_at = db.Column(db.DateTime, nullable=True)
    search_vector = deferred(db.Column(TSVECTOR, db.Computed(ARTICLE_SEARCH_VECTOR_SQL, persisted=True)))

    topics = db.relationship("Topic", secondary=article_topics, back_populates="articles")
    copy_of = db.relationship("Article", remote_side=[id], foreign_keys=[copy_of_id])

    @property
    def last_updated(self):
        """The publication date of this article."""
        return self.date

    @property
    def is_roundup(self):
        return is_roundup_article(self.title, self.url)


class OpinionPiece(db.Model):
    """Op-eds, columns and editorials, kept apart from the news (2026-10-08).

    Ingestion refuses opinion as news (`article_signals.is_opinion_article`)
    and stores it here instead. A separate table on purpose: nothing in the
    news pipeline (grouping, editions, embeddings, summaries, listings) reads
    it, so opinion can't leak into stories. Nothing is fetched for it; it only
    collects what the regular fetches bring in. `content` is what the feed
    supplied.

    Since 2026-10-10 full runs link each piece to the news story it argues
    about (`news_fetcher/opinion_linker.py`): it is embedded from its title
    and teaser, checked against the nearest stories, and, once linked,
    scraped into `full_text` so the story's opinion roundup can read it. The
    link only points from here to a story; no news query reads this table.
    """
    __tablename__ = "opinion_pieces"
    __table_args__ = (
        db.Index("ix_opinion_pieces_date", "date"),
        db.Index("ix_opinion_pieces_outlet_id", "outlet_id"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    title      = db.Column(db.String, nullable=False)
    url        = db.Column(db.String, unique=True, nullable=False)
    source     = db.Column(db.String)
    outlet_id  = db.Column(db.Integer, db.ForeignKey("outlets.id", ondelete="SET NULL"))
    bias_score = db.Column(db.Float)  # the outlet's, copied at ingestion like Article.bias_score
    date       = db.Column(db.DateTime, default=datetime.utcnow)  # published
    fetched_at = db.Column(db.DateTime, default=datetime.utcnow)
    content    = db.Column(db.Text)
    image_url  = db.Column(db.String)
    embedding  = db.Column(Vector(768))  # title + teaser, built like Article embeddings
    # The story this column is about. SET NULL so merging or deleting a story
    # just unlinks its columns.
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id", ondelete="SET NULL"), index=True)
    link_similarity = db.Column(db.Float)
    link_checked_at = db.Column(db.DateTime)  # set once, linked or not, so a piece is checked one time
    full_text  = db.Column(db.Text)  # scraped after linking; NULL when the publisher blocks it
    scrape_status = db.Column(db.String(32))
    stance     = db.Column(db.Text)  # one phrase from the roundup call: what this column argues

    outlet = db.relationship("Outlet")
    story = db.relationship("Story")

    @property
    def has_usable_image(self):
        return bool(self.image_url) and not self.is_roundup


