# Account roles, lowest to highest; each includes everything below it.
# reader:  read every page, change nothing.
# scraper: also run work (fetch, summarize, analyze, rate bias, scrape).
# admin:   also Admin Tools, all configuration, and managing users.
ROLE_READER = "reader"
ROLE_SCRAPER = "scraper"
ROLE_ADMIN = "admin"
ROLES = (ROLE_READER, ROLE_SCRAPER, ROLE_ADMIN)
ROLE_LABELS = {ROLE_READER: "Reader", ROLE_SCRAPER: "Scraper", ROLE_ADMIN: "Admin"}


class User(db.Model, UserMixin):
    __tablename__ = "users"

    id            = db.Column(db.Integer, primary_key=True)
    username      = db.Column(db.String(64), unique=True, nullable=False)
    email         = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(256))
    # Kept in step with role (set_role) for anything that still reads it.
    is_admin      = db.Column(db.Boolean, default=False)
    role          = db.Column(db.String(16), nullable=False, default=ROLE_READER, server_default=ROLE_READER)
    # Overrides UserMixin.is_active: a disabled account can't sign in, and
    # load_user() drops an existing session for it.
    is_active     = db.Column(db.Boolean, nullable=False, default=True, server_default=db.true())
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    last_login_at = db.Column(db.DateTime)

    def has_role(self, minimum):
        """True when this user's role is `minimum` or higher."""
        if self.role not in ROLES:
            return False
        return ROLES.index(self.role) >= ROLES.index(minimum)

    def set_role(self, role):
        if role not in ROLES:
            raise ValueError(f"unknown role {role!r}")
        self.role = role
        self.is_admin = role == ROLE_ADMIN

    @property
    def role_label(self):
        return ROLE_LABELS.get(self.role, self.role)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)


class ScrapeBlocklist(db.Model):
    """
    Domains whose scraped *content* is untrustworthy (paywall/login-wall
    text, near-duplicate boilerplate across articles, etc).

    Non-permanent rows are hit-counted, not blocked outright: `hit_count`
    tracks distinct bad-scrape hits, and `news_fetcher.scraper.is_domain_blocked()`
    only treats the domain as blocked once `hit_count` reaches
    `scraper.BLOCKLIST_MIN_HIT_THRESHOLD` -- a single flaky article no longer
    takes out an entire outlet. `expires_at` (set once that threshold is hit,
    and slid forward on each further hit while active) lets a block lapse on
    its own if the domain's scrapes clean up; `add_to_blocklist()` restarts the
    hit count from zero if the previous hit fell outside
    `scraper.BLOCKLIST_WINDOW_HOURS`, so a stale one-off from months ago
    doesn't count toward a fresh streak. `is_permanent` rows (the seeded
    hard-paywall list, or anything hand-flagged via the admin UI) bypass all
    of this and are always blocked -- see fableaudit.md 1.1 for the incident
    (Fox News, BBC, Toronto Sun, and others silently suppressed for months on
    one bad scrape each) that prompted adding hit-counting and expiry here.
    """
    __tablename__ = "scrape_blocklist"
    __table_args__ = (
        db.Index("ix_scrape_blocklist_domain", "domain"),
    )

    id           = db.Column(db.Integer, primary_key=True)
    domain       = db.Column(db.String, unique=True, nullable=False)
    reason       = db.Column(db.String, nullable=False)
    added_at     = db.Column(db.DateTime, default=datetime.utcnow)
    is_permanent = db.Column(db.Boolean, default=False, nullable=False)
    hit_count    = db.Column(db.Integer, default=1, nullable=False)
    last_hit_at  = db.Column(db.DateTime, default=datetime.utcnow)
    expires_at   = db.Column(db.DateTime, nullable=True)


class IngestionBlock(db.Model):
    """
    Articles refused at ingestion, before anything is stored.

    Distinct from ScrapeBlocklist above, which is about domains whose *content*
    won't scrape -- those articles are still ingested and still count. These
    are never stored at all.

    `kind` picks what the pattern is tested against: "source" is a bare
    substring of the normalized URL, "title_keyword" a bare substring of the
    title. Both are matched case-insensitively. Substring rather than exact
    match is load-bearing for the league domains -- "nfl.com" is what catches
    the *-frontend.pocket.nfl.com hosts, and "nba.com" is what catches
    "wnba.com" -- so entries want to be specific enough not to over-match.
    """
    __tablename__ = "ingestion_blocks"
    __table_args__ = (
        db.UniqueConstraint("kind", "pattern", name="uq_ingestion_block_kind_pattern"),
    )

    id        = db.Column(db.Integer, primary_key=True)
    kind      = db.Column(db.String(16), nullable=False)  # source / title_keyword
    pattern   = db.Column(db.String, nullable=False)
    note      = db.Column(db.String, nullable=True)  # why this is blocked
    is_active = db.Column(db.Boolean, default=True, nullable=False)
    added_at  = db.Column(db.DateTime, default=datetime.utcnow)


class RssFeed(db.Model):
    __tablename__ = "rss_feeds"
    __table_args__ = (
        # The same feed URL can legitimately appear in more than one bucket
        # (e.g. Fox News is both a general-ingestion feed and a right-enrichment
        # feed) — the three source lists in rss_fetcher.py are fetched
        # independently, so uniqueness is per (url, bucket), not per url alone.
        db.UniqueConstraint("url", "bucket", name="uq_rss_feed_url_bucket"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    url        = db.Column(db.String, nullable=False)
    bucket     = db.Column(db.String(32), nullable=False)  # general / right_enrichment / left_enrichment / op_ed
    label      = db.Column(db.String, nullable=True)
    enabled    = db.Column(db.Boolean, default=True, nullable=False)
    added_at   = db.Column(db.DateTime, default=datetime.utcnow)
    # Fetched instead when `url` answers with an HTTP error or can't be
    # parsed; normally a Google News search feed for the same outlet/section.
    fallback_url = db.Column(db.String, nullable=True)


