class PipelineSchedule(db.Model):
    """
    When the scheduler fetches/publishes. Each row is one cron-style firing
    time (hour, America/New_York) tagged as either a full pipeline run
    (fetch + grouping + summaries + edition publish) or a fetch-only run.
    """
    __tablename__ = "pipeline_schedule"
    __table_args__ = (
        db.UniqueConstraint("hour", name="uq_pipeline_schedule_hour"),
    )

    id                = db.Column(db.Integer, primary_key=True)
    hour              = db.Column(db.Integer, nullable=False)  # 0-23, America/New_York
    run_full_pipeline = db.Column(db.Boolean, default=False, nullable=False)
    is_active         = db.Column(db.Boolean, default=True, nullable=False)


class ScheduledFetch(db.Model):
    """
    *What* each scheduled run pulls from the news APIs -- the counterpart to
    PipelineSchedule, which is *when* runs happen.

    One row per category the pipeline queries. `mode` picks the NewsAPI
    endpoint: "query" hits /everything using `query`, "top" hits
    /top-headlines using `country` + `category`. The gnews_* columns are the
    same idea for the GNews provider, kept separate because the two providers
    have different category vocabularies and phrase-matching behaviour.
    """
    __tablename__ = "scheduled_fetches"
    __table_args__ = (
        # `label` keys this fetch's slice of the per-run metrics
        # (run_metrics["topics"]), so duplicate labels would silently
        # overwrite each other's results.
        db.UniqueConstraint("label", name="uq_scheduled_fetch_label"),
    )

    id               = db.Column(db.Integer, primary_key=True)
    label            = db.Column(db.String, nullable=False)
    description      = db.Column(db.String, nullable=True)  # blurb for the manual-fetch presets
    mode             = db.Column(db.String(16), nullable=False, default="query")  # query / top
    # newsapi_* rather than the bare names: a `query` attribute would shadow
    # Flask-SQLAlchemy's Model.query, and the prefix pairs with gnews_* below.
    newsapi_country  = db.Column(db.String(8), nullable=True)   # ISO-2, "top" mode only
    newsapi_category = db.Column(db.String(32), nullable=True)  # NewsAPI category, "top" mode only
    newsapi_query    = db.Column(db.String, nullable=True)      # search terms, "query" mode only
    gnews_query      = db.Column(db.String, nullable=True)
    gnews_category   = db.Column(db.String(32), nullable=True)
    sort_order       = db.Column(db.Integer, default=0, nullable=False)
    is_active        = db.Column(db.Boolean, default=True, nullable=False)


class Edition(db.Model):
    __tablename__ = 'editions'

    id           = db.Column(db.Integer, primary_key=True)
    date         = db.Column(db.Date, nullable=False)
    edition_type = db.Column(db.String(16), nullable=False)  # morning/evening
    created_at   = db.Column(db.DateTime, default=datetime.utcnow)
    published    = db.Column(db.Boolean, default=True)

    __table_args__ = (db.UniqueConstraint('date', 'edition_type', name='uq_edition_date_type'),)

    edition_stories = db.relationship(
        'EditionStory',
        backref='edition',
        lazy='dynamic',
        order_by='EditionStory.rank',
        cascade='all, delete-orphan'
    )


class EditionStory(db.Model):
    __tablename__ = 'edition_stories'
    __table_args__ = (
        db.UniqueConstraint('edition_id', 'story_id',
                            name='uq_edition_story'),
    )

    id                      = db.Column(db.Integer, primary_key=True)
    edition_id              = db.Column(db.Integer, db.ForeignKey('editions.id'), nullable=False)
    story_id                = db.Column(db.Integer, db.ForeignKey('stories.id'), nullable=False)
    rank                    = db.Column(db.Integer, nullable=False)
    headline_score_at_publish = db.Column(db.Float, nullable=True)
    has_updates             = db.Column(db.Boolean, nullable=False, default=False, server_default='false')
    archived_image_path     = db.Column(db.String, nullable=True)
    source_image_url        = db.Column(db.String, nullable=True)
    image_credit_text       = db.Column(db.String(255), nullable=True)
    image_download_status   = db.Column(db.String(32), nullable=True)
    image_downloaded_at     = db.Column(db.DateTime, nullable=True)
    image_width             = db.Column(db.Integer, nullable=True)
    image_height            = db.Column(db.Integer, nullable=True)
    image_bytes             = db.Column(db.Integer, nullable=True)

    story = db.relationship('Story', back_populates='edition_stories', lazy='joined', overlaps="edition_stories,story_ref")


class ConfigSetting(db.Model):
    """A setting saved from the admin UI that overrides an environment
    variable (aggregator/config_store.py). Secrets are stored only as
    `secret_value`, Fernet-encrypted (aggregator/secret_box.py), with their
    last four characters in `hint` so the page can tell keys apart without
    decrypting them."""
    __tablename__ = "config_settings"

    key          = db.Column(db.String(64), primary_key=True)
    value        = db.Column(db.Text, nullable=True)
    secret_value = db.Column(db.Text, nullable=True)
    hint         = db.Column(db.String(8), nullable=True)
    updated_at   = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    updated_by   = db.Column(db.String(64), nullable=True)


# The API (aggregator/api/, served by aggregator/api_app.py). Scopes a
# device token or API key can carry; "read" covers every read endpoint and the user's own
# preferences and NewsBox read state; "summarize" lets it queue summaries
# (POST /stories/{id}/summarize) and edit or run the user's schedule.
API_SCOPES = ("read", "summarize")


class ApiDevice(db.Model):
    """A bearer token for the API: a phone that paired with a code
    (kind "device") or an API key an admin created in Settings for any other
    client (kind "key"). Only the SHA-256 of the token is stored; the token
    itself is shown once, to the device that paired or the admin."""
    __tablename__ = "api_devices"

    id           = db.Column(db.Integer, primary_key=True)
    user_id      = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    name         = db.Column(db.String(80), nullable=False)
    kind         = db.Column(db.String(16), nullable=False, default="device", server_default="device")
    token_hash   = db.Column(db.String(64), nullable=False, unique=True)
    scopes       = db.Column(db.String(200), nullable=False, default="read", server_default="read")
    created_at   = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    expires_at   = db.Column(db.DateTime, nullable=True)
    last_used_at = db.Column(db.DateTime, nullable=True)
    last_ip      = db.Column(db.String(64), nullable=True)
    revoked_at   = db.Column(db.DateTime, nullable=True)

    user = db.relationship("User", backref=db.backref("api_devices", lazy="dynamic", cascade="all, delete-orphan"))

    @property
    def scope_list(self):
        return [s for s in (self.scopes or "").split() if s]

    @property
    def is_live(self):
        return self.revoked_at is None and (self.expires_at is None or self.expires_at > datetime.utcnow())


class ApiPairingCode(db.Model):
    """A one-time code an admin creates for a user; a phone trades it for a
    device token at POST /api/v1/devices/pair. Lives ten minutes, works once,
    and is stored only as a hash."""
    __tablename__ = "api_pairing_codes"

    id          = db.Column(db.Integer, primary_key=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    code_hash   = db.Column(db.String(64), nullable=False, unique=True)
    scopes      = db.Column(db.String(200), nullable=False, default="read", server_default="read")
    created_by  = db.Column(db.String(64), nullable=True)
    created_at  = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    expires_at  = db.Column(db.DateTime, nullable=False)
    used_at     = db.Column(db.DateTime, nullable=True)
    device_id   = db.Column(db.Integer, db.ForeignKey("api_devices.id", ondelete="SET NULL"), nullable=True)

    user = db.relationship("User")


class ApiRateCounter(db.Model):
    """Request counts per key (a device, an IP, pairing attempts by IP) per
    fixed window, shared by every API worker (aggregator/api/ratelimit.py)."""
    __tablename__ = "api_rate_counters"

    key          = db.Column(db.String(120), primary_key=True)
    window_start = db.Column(db.DateTime, primary_key=True)
    count        = db.Column(db.Integer, nullable=False, default=0, server_default="0")


class NewsBoxItem(db.Model):
    """A story in one user's NewsBox (aggregator/newsbox.py): summarized for
    them from a client (a request or a bookmark) or by their schedule. `state` goes
    pending -> in_progress -> ready, or failed; the summary itself lives on
    the Story and is shared by everyone."""
    __tablename__ = "newsbox_items"
    __table_args__ = (
        db.UniqueConstraint("user_id", "story_id", name="uq_newsbox_user_story"),
        db.Index("ix_newsbox_user_added", "user_id", "added_at"),
        db.Index("ix_newsbox_story_state", "story_id", "state"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    # Null while a Breaking headline sent from the app is still being
    # scraped (feed_entry_id is set then); the scrape job fills it in.
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id", ondelete="CASCADE"), nullable=True)
    feed_entry_id = db.Column(db.Integer, db.ForeignKey("feed_entries.id", ondelete="SET NULL"), nullable=True)
    origin     = db.Column(db.String(16), nullable=False)   # requested / saved / scheduled / breaking
    depth      = db.Column(db.String(24), nullable=False, default="summary", server_default="summary")
    state      = db.Column(db.String(16), nullable=False, default="pending", server_default="pending")
    # Items from one scheduled run share this id.
    run_id     = db.Column(db.String(64), nullable=True)
    is_unread  = db.Column(db.Boolean, nullable=False, default=True, server_default=db.true())
    # What an unfinished item is waiting on: scrape -> group -> summary ->
    # analysis (newsbox.STEPS), shown as a progress bar in the app.
    step       = db.Column(db.String(16), nullable=True)
    error      = db.Column(db.String(300), nullable=True)
    added_at   = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    ready_at   = db.Column(db.DateTime, nullable=True)

    story = db.relationship("Story")
    feed_entry = db.relationship("FeedEntry")
    user = db.relationship("User", backref=db.backref("newsbox_items", lazy="dynamic", cascade="all, delete-orphan"))


class SummarySchedule(db.Model):
    """One user's scheduled summaries: when to run and which sections, as JSON
    checked by aggregator.newsbox.clean_schedule. The scheduler container
    runs every schedule whose next_run_at has passed (run_due_schedules)."""
    __tablename__ = "summary_schedules"

    user_id     = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), primary_key=True)
    settings    = db.Column(db.Text, nullable=False, default="{}", server_default="{}")
    next_run_at = db.Column(db.DateTime, nullable=True, index=True)
    last_run_at = db.Column(db.DateTime, nullable=True)
    updated_at  = db.Column(db.DateTime, nullable=False, default=datetime.utcnow, onupdate=datetime.utcnow)

    user = db.relationship("User", backref=db.backref("summary_schedule", uselist=False, cascade="all, delete-orphan"))


class Bookmark(db.Model):
    """A story a user saved in the app, kept as a time capsule: versioned
    snapshots (BookmarkSnapshot) of the story, its summaries, analysis,
    coverage, columns, full text, images and page captures, written to
    files under BOOKMARK_STORAGE_DIR (aggregator/bookmarks.py). The story
    link is SET NULL on delete, so a bookmark outlives regrouping; `title`
    keeps its name."""
    __tablename__ = "bookmarks"
    __table_args__ = (
        db.UniqueConstraint("user_id", "story_id", name="uq_bookmark_user_story"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id", ondelete="SET NULL"), nullable=True)
    title      = db.Column(db.String(500), nullable=False)
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    story = db.relationship("Story")
    user = db.relationship("User", backref=db.backref("bookmarks", lazy="dynamic", cascade="all, delete-orphan"))
    snapshots = db.relationship("BookmarkSnapshot", back_populates="bookmark", cascade="all, delete-orphan",
                                order_by="BookmarkSnapshot.version")


class BookmarkSnapshot(db.Model):
    """One version of a bookmark's time capsule. `status` is the text and
    images (pending -> building -> ready, or failed / over_quota);
    `captures` is the page PDFs and screenshots, done separately by the
    capture container (pending -> done, or partial / unavailable / failed /
    over_quota). `size_bytes` counts against the user's storage cap."""
    __tablename__ = "bookmark_snapshots"
    __table_args__ = (
        db.UniqueConstraint("bookmark_id", "version", name="uq_bookmark_snapshot_version"),
    )

    id          = db.Column(db.Integer, primary_key=True)
    bookmark_id = db.Column(db.Integer, db.ForeignKey("bookmarks.id", ondelete="CASCADE"), nullable=False, index=True)
    version     = db.Column(db.Integer, nullable=False)
    status      = db.Column(db.String(16), nullable=False, default="pending", server_default="pending")
    captures    = db.Column(db.String(16), nullable=False, default="pending", server_default="pending")
    size_bytes  = db.Column(db.BigInteger, nullable=False, default=0, server_default="0")
    asset_count = db.Column(db.Integer, nullable=False, default=0, server_default="0")
    error       = db.Column(db.String(300), nullable=True)
    created_at  = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    finished_at = db.Column(db.DateTime, nullable=True)

    bookmark = db.relationship("Bookmark", back_populates="snapshots")


class FeedEntry(db.Model):
    """A headline seen in a general RSS feed, stored minutes after it is
    published and before anything scrapes it (aggregator/breaking.py). The
    Breaking banner on Headlines and /api/v1/breaking list the ones that have
    no article yet; "scrape now" queues a job that runs the entry through the
    normal ingestion. `url` is the normalized link, which for a Google News
    feed is still the news.google.com one until the job resolves it.
    `scrape_state` goes new -> queued -> done, or skipped / failed.
    `is_breaking` and `outlet_count` are set by the poller
    (news_fetcher/breaking_feed.py); `cluster_id` is the first entry that
    reported the same event, so a cluster shows once."""
    __tablename__ = "feed_entries"
    __table_args__ = (
        db.Index("ix_feed_entries_published_at", "published_at"),
        db.Index("ix_feed_entries_breaking", "is_breaking", "published_at"),
    )

    id            = db.Column(db.Integer, primary_key=True)
    url           = db.Column(db.String(2000), nullable=False, unique=True)
    link          = db.Column(db.String(2000), nullable=False)
    title         = db.Column(db.String(500), nullable=False)
    source_name   = db.Column(db.String(200), nullable=False)
    feed_url      = db.Column(db.String(2000), nullable=True)
    image_url     = db.Column(db.String(2000), nullable=True)
    content       = db.Column(db.Text, nullable=True)
    published_at  = db.Column(db.DateTime, nullable=False)
    first_seen_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    article_id    = db.Column(db.Integer, db.ForeignKey("articles.id", ondelete="SET NULL"), nullable=True)
    scrape_state  = db.Column(db.String(16), nullable=False, default="new", server_default="new")
    scrape_note   = db.Column(db.String(300), nullable=True)
    requested_at  = db.Column(db.DateTime, nullable=True)
    outlet_count  = db.Column(db.Integer, nullable=False, default=1, server_default="1")
    is_breaking   = db.Column(db.Boolean, nullable=False, default=False, server_default=db.false())
    cluster_id    = db.Column(db.Integer, nullable=True)

    article = db.relationship("Article")


class ArticleLeanRating(db.Model):
    """One rating of an article's own lean (aggregator/article_lean.py): the
    AI's, with its one-line reason, or a reader's from the Rate lean dialog,
    with an optional note. The newest applied one is the article's
    bias_score; AI ratings the dialog showed but nobody saved stay unapplied
    and are reused next time instead of asking the model again."""
    __tablename__ = "article_lean_ratings"
    __table_args__ = (
        db.Index("ix_lean_article_created", "article_id", "created_at"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    article_id = db.Column(db.Integer, db.ForeignKey("articles.id", ondelete="CASCADE"), nullable=False)
    user_id    = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="SET NULL"), nullable=True)
    source     = db.Column(db.String(16), nullable=False)  # "ai" or "reader"
    score      = db.Column(db.Integer, nullable=False)
    reason     = db.Column(db.Text, nullable=True)  # the AI's WHY line, or the reader's note
    applied    = db.Column(db.Boolean, nullable=False, default=False, server_default="false")
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    user = db.relationship("User")


class ReadItem(db.Model):
    """A story or an article one user marked read (aggregator/reads.py):
    from the reading-glasses button on Headlines, the story and article
    pages, or a swipe in the app (/api/v1/me/read). Read stories drop out of
    that user's Headlines; Recently Read lists both kinds, newest first.
    Exactly one of story_id and article_id is set."""
    __tablename__ = "read_items"
    __table_args__ = (
        db.UniqueConstraint("user_id", "story_id", name="uq_read_user_story"),
        db.UniqueConstraint("user_id", "article_id", name="uq_read_user_article"),
        db.CheckConstraint("(story_id IS NULL) <> (article_id IS NULL)", name="ck_read_one_target"),
        db.Index("ix_read_user_read_at", "user_id", "read_at"),
    )

    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id", ondelete="CASCADE"), nullable=True)
    article_id = db.Column(db.Integer, db.ForeignKey("articles.id", ondelete="CASCADE"), nullable=True)
    read_at    = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    story = db.relationship("Story")
    article = db.relationship("Article")
    user = db.relationship("User", backref=db.backref("read_items", lazy="dynamic", cascade="all, delete-orphan"))


class StorySkip(db.Model):
    """A story one user passed on in the app's Swipe deck (aggregator/skips.py).
    Scheduled runs never summarize it for that user; it can still be asked
    for from the story page, and it drops out of their deck."""
    __tablename__ = "story_skips"
    __table_args__ = (db.UniqueConstraint("user_id", "story_id", name="uq_skip_user_story"),)

    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    story_id   = db.Column(db.Integer, db.ForeignKey("stories.id", ondelete="CASCADE"), nullable=False)
    skipped_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    story = db.relationship("Story")
    user = db.relationship("User", backref=db.backref("story_skips", lazy="dynamic", cascade="all, delete-orphan"))
